import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"; tok=[None]; stats={"retries":0,"404":[]}
def req(path,method="GET",auth=True):
    while True:
        if auth and not tok[0]:
            tok[0]=req("/token","POST",False)["token"]
        h={"Authorization":"Bearer "+tok[0]} if auth else {}
        r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
        try:
            with urllib.request.urlopen(r,timeout=30) as f: return json.loads(f.read())
        except urllib.error.HTTPError as e:
            stats["retries"]+=1
            if e.code==401: tok[0]=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After") or "1"; time.sleep(float(ra)); continue
            if e.code==404 and path.startswith("/customers"): return None
            time.sleep(0.5)
        except Exception: stats["retries"]+=1; time.sleep(0.5)
seen={}; dups=0; path="/orders?page=1"; pages=0
while path:
    d=req(path); pages+=1
    for o in d["items"]:
        if o["id"] in seen: dups+=1
        else: seen[o["id"]]=o
    path=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={}; reg={k:0 for k in ["north","south","east","west"]}; n=0; odd=set(); naive=0
for o in seen.values():
    if o["status"]!="shipped": 
        if o["status"] not in("placed","cancelled","returned"): odd.add(o["status"])
        continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: naive+=1; t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
    cu=cust[c]
    if cu is None: stats["404"].append(o["id"]); continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v; n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res,pages,len(seen),odd,naive,stats)
EOF
